INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (41200,0,0,'$n has captured a Colossal Viseclaw!',16,0,100.0,0,0,34494,68930,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (41200,3,0,'Ku-Yao\'s bedroll is empty. He\'s not here.',42,0,100.0,0,0,0,66371,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,0,0,'Is it gettin\' hot in here?',14,0,100.0,0,0,0,70130,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,1,0,'Now entering the arena: a Rank 1 $r $c, $n! $n is pretty new around here, so go easy!',14,0,100.0,22,0,34757,68842,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,2,0,'Now entering the arena: an up-and-coming Rank 2 $c, $n!',14,0,100.0,22,0,34757,68888,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,3,0,'Put your hands together for $n! $n is a Rank 3 $c.',14,0,100.0,22,0,34757,68889,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,4,0,'Here\'s our challenger. Today, we welcome a Rank 4 $r $c, $n!',14,0,100.0,22,0,34757,68890,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,5,0,'Now entering the arena, we have a very talented $c. Say hello to $n, a Rank 5 brawler!',14,0,100.0,22,0,34757,68891,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,6,0,'Look out... here comes the deadly Rank 6 $r, $n!',14,0,100.0,22,0,34761,68892,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,7,0,'Now entering the arena: a returning champion. Our Rank 7 $c, $n!',14,0,100.0,22,0,34757,68893,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,8,0,'Now entering the arena: You know $ghim:her;. You love $ghim:her;. Give it up for our Rank 8 Brawler, $N!!',14,0,100.0,22,0,34757,68894,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,0,'It\'s official! $n managed not to die. Great job not dying, $n!',14,0,100.0,0,0,34341,68846,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,1,'Well well well! $n wins! Looks like I owe someone some money.',14,0,100.0,0,0,34758,68844,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,2,'$n is our victor!',14,0,100.0,0,0,34758,68840,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,3,'Congratulations, $n! Try not to leave any bloody footprints outside of the arena.',14,0,100.0,0,0,34758,68845,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,4,'Keep \'em comin\', $n.',14,0,100.0,0,0,34758,69895,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,5,'Brilliant victory, $n! Now get back in line.',14,0,100.0,0,0,34758,69890,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,9,6,'$n wins! $n wins!',14,0,100.0,0,0,34758,69896,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,0,'$n, $n, $n. Next time, try not to die so much.',14,0,100.0,0,0,34755,68849,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,1,'I think we\'ve seen just about enough of this. Am I right?',14,0,100.0,0,0,0,70145,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,2,'Sorry, $n. Now would you kindly remove your corpse so that the others can have a go?',14,0,100.0,0,0,34755,69891,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,3,'$gHis:Her; name was $n.',14,0,100.0,0,0,34755,69889,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,4,'That... did not end well.',14,0,100.0,0,0,34755,68848,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,5,'Ouch... sorry, $n. Get back in line and try again.',14,0,100.0,0,0,34755,68841,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,10,6,'Honestly, $n... were you even trying?',14,0,100.0,0,0,34755,69892,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,11,0,'Looks like every day is Hallow\'s End for this... thing. Give up some screams for Ooliss!',14,0,100.0,22,0,0,126125,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,12,0,'We don\'t have all night. Hurry it up already!',14,0,100.0,0,0,0,70139,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,13,0,'Do you smell smoke?',14,0,100.0,0,0,0,70142,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,14,0,'We also welcome everybody\'s favorite frosty feathered friend: Dippy!',14,0,100.0,0,0,34760,69855,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,15,0,'And their challenger, Bill, the custodial engineer of death! Wait... what? Bill! What are you doing in there?',14,0,100.0,0,0,34760,126126,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,16,0,'From deep within the bowels of Blackrock Mountain, it\'s Sanoriak, master of flame!',14,0,100.0,0,0,34760,69945,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,17,0,'Kindly insert a gold coin for a battle with Master Paku!',14,0,100.0,0,0,34760,126131,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,18,0,'Oh, the huge manatee! It\'s here to seal the deal... DOOMFLIPPER!',14,0,100.0,0,0,34760,126124,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,19,0,'Brawl\'gar veterans may remember Blat, the self-replicating ooze. Today, we meet his meaner, uglier, older sister: Splat!',14,0,100.0,0,0,34760,74147,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,20,0,'In the other corner, a master of both shadows AND interior lighting... it\'s Shadowmaster Aameen!',14,0,100.0,0,0,34760,126128,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,21,0,'And in the other corner, a hunter of incomprehensible spectacular amazing splendor! It\'s Johnny Awesome!',14,0,100.0,0,0,34760,126135,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,22,0,'Get fired up for the djinn who will literally melt your heart, it\'s Burnstachio!',14,0,100.0,0,0,34760,126137,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,23,0,'And... Meatball.',14,0,100.0,0,0,34760,70059,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,24,0,'Their partnership was never meant to be. It actually makes me sick a little bit. Here comes GG Engineering!',14,0,100.0,0,0,34760,69869,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,25,0,'All the way from the gloomy roads of Duskwood, it\'s Stitches!',14,0,100.0,0,0,34760,126121,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,26,0,'And now for some soul-pounding beats from the musical underground, it\'s Thwack U and his dancers!',14,0,100.0,0,0,34760,126139,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,27,0,'He\'s probably the most deadly brawler we\'ve ever had here at the Brawl\'gar Arena. Unfortunately, he\'s a little out of his element. Everybody raise your glass for Razorgrin!',14,0,100.0,0,0,34760,73725,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,28,0,'Five on one hardly seems fair, but come on... they\'re half-dead gnomes. It\'s the leper gnome quintet!',14,0,100.0,0,0,34760,69852,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,29,0,'In the other corner, a pirate with a lethal definition of head cannon! Put your hooks together for Blackmange!',14,0,100.0,0,0,34760,126140,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,30,0,'In the other corner... a really big dinosaur!',14,0,100.0,0,0,34760,126130,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,31,0,'Up next, probably the weakest, ugliest, and least genius combatant I\'ve ever seen. It\'s the stupid, smelly gnome, Millie Watt! Everybody boo!',14,0,100.0,0,0,34760,69860,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,32,0,'And our other challenger, a worm with a serious fire fetish. Come on, Carl! Don\'t you know flames can kill?',14,0,100.0,0,0,34760,126134,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,34,0,'Aww... look at the cute little snake, Nibbleh! Go ahead, let him nibble on your toes. Let\'s see what happens.',14,0,100.0,0,0,34760,74141,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,35,0,'In the other corner, a challenger so ancient no one remembers his actual name. Let\'s call him Serpent of Old!',14,0,100.0,0,0,34760,126104,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,36,0,'And now for the challenger that cost us so much... it\'s Ray D. Tear!',14,0,100.0,0,0,34760,126136,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,37,0,'Also entering the arena: Everybody\'s favorite magical 12-foot-tall corpse, Fjoll! Am I pronouncing that right?',14,0,100.0,22,0,34756,69954,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,40,0,'Some of you veterans might remember this guy. He may be Broken, but today, he means to break you! It\'s Akama!',14,0,100.0,22,0,34341,69953,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,43,0,'And in the other corner, we have... a big cloud of scary floating eyes? This doesn\'t look good.',14,0,100.0,22,0,34756,69959,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,48,0,'In the other corner... a disgusting green pile of goblin idiocy, riding on a lumbering chariot of shame. It\'s Fran and Riddoh! Everybody boo!',14,0,100.0,22,0,34756,69943,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,57,0,'Time\'s nearly up!',14,0,100.0,0,0,0,70141,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,60,0,'Hey hey! Look what we\'ve scooped up for you today... it\'s Blat!',14,0,100.0,22,0,34756,69940,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,69,0,'In the other corner, we have Vian, the flame-flinging follower of the Thunder King!',14,0,100.0,22,0,34756,69937,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,72,0,'He doesn\'t need blades or magic to defeat his enemies. Our next challenger, Hexos, fights his foes with the awesome powers of GEOMETRY!',14,0,100.0,22,0,34756,74136,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,75,0,'He\'s got two modes. Both modes are labeled "KILL". Let\'s hear it for T440!',14,0,100.0,22,0,34756,74138,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,87,0,'What\'s better than an explosion? Lots and lots of explosions, of course! In this corner, we have Big Badda Boom!!',14,0,100.0,22,0,34756,74140,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,92,0,'You wanna make an omelet, you\'re gonna have to break a few eggs.',14,0,100.0,0,0,34755,69893,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,94,0,'He represents everything that is just, and righteous, and several other virtues which are of no interest to most of you. It\'s the draenei paladin, Ahoo\'ru!',14,0,100.0,22,0,34756,73078,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,100,0,'We have a special guest today: the always-endearing, ever-resilient, Millhouse Manastorm! Good luck, MillMan!',14,0,100.0,22,0,34756,69955,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,103,0,'We found this one scuttling in circles in Silithus. From the looks of him, somebody mostly killed him already. It\'s Ixx!',14,0,100.0,22,0,34756,69946,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,111,0,'He may be a huge chicken, but he\'ll still put up a fight. It\'s Tyson Sanders!',14,0,100.0,22,0,34756,74137,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,126,0,'Well, wrap me in leather and tug my leash: it\'s Dungeon Master Vishas!',14,0,100.0,22,0,34756,69939,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,129,0,'When I see her smile, it makes me smile. When she casts a spell, it puts a spell on me. When I see her horns, it makes me feel... intrigued. It\'s Dominika!',14,0,100.0,22,0,34756,69950,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,132,0,'And in this corner! He\'s angry. He\'s deadly. He\'s a little bit adorable. Straight out of Neverest, it\'s Crush!',14,0,100.0,22,0,34756,69948,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,147,0,'I never thought I\'d see the day! Our former champion, out of retirement! Put your big, beefy hands together for Leona Earthwind!',14,0,100.0,22,0,34756,70058,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,153,0,'Up next, it\'s Millie Watt! I used to date her in engineering school!',14,0,100.0,22,0,34756,69951,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67260,154,0,'Ahhh ha ha ha! So much blood! Nice.',14,0,100.0,0,0,34758,69894,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67267,0,0,'Blood and honor, $c.',12,0,100.0,66,0,0,70088,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67267,1,0,'Let me know if you want to brawl, $r.',12,0,100.0,66,0,0,70087,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67267,2,0,'You fighting today, $c?',12,0,100.0,66,0,0,70086,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67268,0,0,'Feel the flames\' embrace!',14,0,100.0,0,0,0,70115,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67268,0,1,'You can\'t run forever!',12,0,100.0,0,0,0,70119,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67268,0,2,'There is no escape...',12,0,100.0,0,0,0,70116,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67268,0,3,'Your time has come.',12,0,100.0,0,0,0,70117,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67268,1,0,'Is it cold in here...?',12,0,100.0,0,0,34747,70120,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67487,0,0,'I\'m going to cover, you blow them up!',14,0,100.0,0,0,0,68966,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67487,1,0,'Pick up the slack Max, I\'m carrying you!',14,0,100.0,0,0,0,68967,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67487,2,0,'My teammate is to blame for everything...',14,0,100.0,0,0,0,68971,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67488,0,0,'GG Engineering is gonna mop the floor with your sorry mug!',14,0,100.0,0,0,0,68970,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67488,1,0,'Bo, your death ray doesn\'t work as advertised!',14,0,100.0,0,0,0,68964,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67488,2,0,'If we survive this, remind me to find a competent partner!',14,0,100.0,0,0,34341,68965,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67511,3,0,'Hugs... we want hugs...',14,0,100.0,0,0,0,71188,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67511,4,0,'Heigh-ho... heigh-ho... OH NO!',14,0,100.0,0,0,0,71191,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67514,0,0,'Hugs... we want hugs...',14,0,100.0,0,0,34341,71188,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67515,3,0,'Hugs... we want hugs...',14,0,100.0,0,0,0,71188,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67516,0,0,'Heigh-ho... heigh-ho... OH NO!',14,0,100.0,0,0,0,71191,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,0,0,'MEATBALL HUNGRY!',14,0,100.0,0,0,0,87715,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,1,0,'MEATBALL FEEL FUNNY!',14,0,100.0,0,0,0,70092,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,2,0,'MEATBALL EAT WHAT MEATBALL WANT!',14,0,100.0,0,0,0,87708,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,3,0,'MEATBALL BELLY GURGLE!',14,0,100.0,0,0,0,87716,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,4,0,'MEATBALL BELLY HURTS!',14,0,100.0,0,0,0,70094,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67573,15,0,'BLLAAAGGGGHHHHH!',14,0,100.0,0,0,0,70097,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67591,0,0,'You really shouldn\'t play with this stuff. Someone could get hurt.',14,0,100.0,0,0,34756,28864,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (67591,1,0,'Look at you! HAH!',14,0,100.0,11,0,0,69165,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,0,0,'Now entering the arena: You know $ghim:her;. You love $ghim:her;. Give it up for our Rank 8 Brawler, $N!!',14,0,100.0,22,0,34757,68894,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,1,0,'Now entering the arena: a Rank 1 $r $c, $n! $n is pretty new around here, so go easy!',14,0,100.0,22,0,34757,68842,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,2,0,'Now entering the arena: an up-and-coming Rank 2 $c, $n!',14,0,100.0,22,0,34757,68888,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,3,0,'Put your hands together for $n! $n is a Rank 3 $c.',14,0,100.0,22,0,34757,68889,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,4,0,'Here\'s our challenger. Today, we welcome a Rank 4 $r $c, $n!',14,0,100.0,22,0,34757,68890,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,5,0,'Now entering the arena, we have a very talented $c. Say hello to $n, a Rank 5 brawler!',14,0,100.0,22,0,34757,68891,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,6,0,'Look out... here comes the deadly Rank 6 $r, $n!',14,0,100.0,22,0,34761,68892,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,7,0,'Now entering the arena: a returning champion. Our Rank 7 $c, $n!',14,0,100.0,22,0,34757,68893,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,0,'It\'s official! $n managed not to die. Great job not dying, $n!',14,0,100.0,0,0,34341,68846,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,1,'Well well well! $n wins! Looks like I owe someone some money.',14,0,100.0,0,0,34758,68844,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,2,'$n is our victor!',14,0,100.0,0,0,34758,68840,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,3,'Congratulations, $n! Try not to leave any bloody footprints outside of the arena.',14,0,100.0,0,0,34758,68845,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,4,'Keep \'em comin\', $n.',14,0,100.0,0,0,34758,69895,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,5,'Brilliant victory, $n! Now get back in line.',14,0,100.0,0,0,34758,69890,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,9,6,'$n wins! $n wins!',14,0,100.0,0,0,34758,69896,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,0,'$n, $n, $n. Next time, try not to die so much.',14,0,100.0,0,0,34755,68849,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,1,'I think we\'ve seen just about enough of this. Am I right?',14,0,100.0,0,0,0,70145,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,2,'Sorry, $n. Now would you kindly remove your corpse so that the others can have a go?',14,0,100.0,0,0,34755,69891,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,3,'$gHis:Her; name was $n.',14,0,100.0,0,0,34755,69889,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,4,'That... did not end well.',14,0,100.0,0,0,34755,68848,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,5,'Ouch... sorry, $n. Get back in line and try again.',14,0,100.0,0,0,34755,68841,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,10,6,'Honestly, $n... were you even trying?',14,0,100.0,0,0,34755,69892,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,11,0,'Looks like every day is Hallow\'s End for this... thing. Give up some screams for Ooliss!',14,0,100.0,22,0,0,126125,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,12,0,'We don\'t have all night. Hurry it up already!',14,0,100.0,0,0,0,70139,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,13,0,'Do you smell smoke?',14,0,100.0,0,0,0,70142,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,14,0,'We also welcome everybody\'s favorite frosty feathered friend: Dippy!',14,0,100.0,0,0,34760,69855,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,15,0,'And their challenger, Bill, the custodial engineer of death! Wait... what? Bill! What are you doing in there?',14,0,100.0,0,0,34760,126126,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,16,0,'From deep within the bowels of Blackrock Mountain, it\'s Sanoriak, master of flame!',14,0,100.0,0,0,34760,69945,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,17,0,'Kindly insert a gold coin for a battle with Master Paku!',14,0,100.0,0,0,34760,126131,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,18,0,'Oh, the huge manatee! It\'s here to seal the deal... DOOMFLIPPER!',14,0,100.0,0,0,34760,126124,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,20,0,'In the other corner, a master of both shadows AND interior lighting... it\'s Shadowmaster Aameen!',14,0,100.0,0,0,34760,126128,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,21,0,'And in the other corner, a hunter of incomprehensible spectacular amazing splendor! It\'s Johnny Awesome!',14,0,100.0,0,0,34760,126135,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,22,0,'Get fired up for the djinn who will literally melt your heart, it\'s Burnstachio!',14,0,100.0,0,0,34760,126137,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,23,0,'And... Meatball.',14,0,100.0,0,0,34760,70059,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,24,0,'Their partnership was never meant to be. It actually makes me sick a little bit. Here comes GG Engineering!',14,0,100.0,0,0,34760,69869,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,25,0,'All the way from the gloomy roads of Duskwood, it\'s Stitches!',14,0,100.0,0,0,34760,126121,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,26,0,'And now for some soul-pounding beats from the musical underground, it\'s Thwack U and his dancers!',14,0,100.0,0,0,34760,126139,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,27,0,'He\'s probably the most deadly brawler we\'ve ever had here at the Brawl\'gar Arena. Unfortunately, he\'s a little out of his element. Everybody raise your glass for Razorgrin!',14,0,100.0,0,0,34760,73725,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,28,0,'Five on one hardly seems fair, but come on... they\'re half-dead gnomes. It\'s the leper gnome quintet!',14,0,100.0,0,0,34760,69852,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,29,0,'In the other corner, a pirate with a lethal definition of head cannon! Put your hooks together for Blackmange!',14,0,100.0,0,0,34760,126140,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,30,0,'In the other corner... a really big dinosaur!',14,0,100.0,0,0,34760,126130,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,31,0,'Up next, probably the weakest, ugliest, and least genius combatant I\'ve ever seen. It\'s the stupid, smelly gnome, Millie Watt! Everybody boo!',14,0,100.0,0,0,34760,69860,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,32,0,'And our other challenger, a worm with a serious fire fetish. Come on, Carl! Don\'t you know flames can kill?',14,0,100.0,0,0,34760,126134,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,33,0,'And in the other corner, it\'s that terrible trio... Hudson, Stuffshrew, and Dupree from the Ogrewatch Team!',14,0,100.0,0,0,34760,126138,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,34,0,'Aww... look at the cute little snake, Nibbleh! Go ahead, let him nibble on your toes. Let\'s see what happens.',14,0,100.0,0,0,34760,74141,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,35,0,'In the other corner, a challenger so ancient no one remembers his actual name. Let\'s call him Serpent of Old!',14,0,100.0,0,0,34760,126104,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,36,0,'And now for the challenger that cost us so much... it\'s Ray D. Tear!',14,0,100.0,0,0,34760,126136,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,37,0,'Also entering the arena: Everybody\'s favorite magical 12-foot-tall corpse, Fjoll! Am I pronouncing that right?',14,0,100.0,22,0,34756,69954,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,40,0,'Some of you veterans might remember this guy. He may be Broken, but today, he means to break you! It\'s Akama!',14,0,100.0,22,0,34341,69953,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,41,0,'Ahhh ha ha ha! So much blood! Nice.',14,0,100.0,0,0,34758,69894,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,43,0,'And in the other corner, we have... a big cloud of scary floating eyes? This doesn\'t look good.',14,0,100.0,22,0,34756,69959,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,46,0,'What\'s better than an explosion? Lots and lots of explosions, of course! In this corner, we have Big Badda Boom!!',14,0,100.0,22,0,34756,74140,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,48,0,'In the other corner... a disgusting green pile of goblin idiocy, riding on a lumbering chariot of shame. It\'s Fran and Riddoh! Everybody boo!',14,0,100.0,22,0,34756,69943,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,51,0,'I never thought I\'d see the day! Our former champion, out of retirement! Put your big, beefy hands together for Leona Earthwind!',14,0,100.0,22,0,34756,70058,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,57,0,'Time\'s nearly up!',14,0,100.0,0,0,0,70141,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,58,0,'You wanna make an omelet, you\'re gonna have to break a few eggs.',14,0,100.0,0,0,34755,69893,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,60,0,'Hey hey! Look what we\'ve scooped up for you today... it\'s Blat!',14,0,100.0,22,0,34756,69940,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,63,0,'He\'s got two modes. Both modes are labeled "KILL". Let\'s hear it for T440!',14,0,100.0,22,0,34756,74138,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,66,0,'The fire\'s coming!',14,0,100.0,0,0,0,70143,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,69,0,'In the other corner, we have Vian, the flame-flinging follower of the Thunder King!',14,0,100.0,22,0,34756,69937,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,72,0,'He doesn\'t need blades or magic to defeat his enemies. Our next challenger, Hexos, fights his foes with the awesome powers of GEOMETRY!',14,0,100.0,22,0,34756,74136,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,78,0,'We found this one scuttling in circles in Silithus. From the looks of him, somebody mostly killed him already. It\'s Ixx!',14,0,100.0,22,0,34756,69946,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,94,0,'He represents everything that is just, and righteous, and several other virtues which are of no interest to most of you. It\'s the draenei paladin, Ahoo\'ru!',14,0,100.0,22,0,34756,73078,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,100,0,'We have a special guest today: the always-endearing, ever-resilient, Millhouse Manastorm! Good luck, MillMan!',14,0,100.0,22,0,34756,69955,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,111,0,'He may be a huge chicken, but he\'ll still put up a fight. It\'s Tyson Sanders!',14,0,100.0,22,0,34756,74137,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,126,0,'Well, wrap me in leather and tug my leash: it\'s Dungeon Master Vishas!',14,0,100.0,22,0,34756,69939,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,129,0,'When I see her smile, it makes me smile. When she casts a spell, it puts a spell on me. When I see her horns, it makes me feel... intrigued. It\'s Dominika!',14,0,100.0,22,0,34756,69950,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,132,0,'And in this corner! He\'s angry. He\'s deadly. He\'s a little bit adorable. Straight out of Neverest, it\'s Crush!',14,0,100.0,22,0,34756,69948,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,141,0,'Get ready to dance! Deeken\'s in the house!',14,0,100.0,22,0,34756,69957,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68323,153,0,'Up next, it\'s Millie Watt! I used to date her in engineering school!',14,0,100.0,22,0,34756,69951,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68363,3,0,'$n has most generously paid for everyone\'s brawling potions. Get them while they\'re hot and bubbly!',14,0,100.0,0,0,80244,124358,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68403,0,0,'Bah! I had my whole paycheck riding on that one!',14,0,100.0,0,0,0,70659,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68405,0,0,'$n! $n! $n!',14,0,100.0,4,0,0,70128,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68405,3,0,'AYYAYAAYAA!',14,0,100.0,0,0,0,20311,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68406,3,0,'I LOSE? NO YOU LOSE!',14,0,100.0,0,0,80244,70661,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68408,0,0,'Let me know if you want to fight, $r.',12,0,100.0,1,0,0,70071,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68408,3,0,'If you want to join the brawl, just let me know.',12,0,100.0,1,0,0,70072,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68526,0,0,'This round\'s on $n! Free drinks for the next two minutes!',14,0,100.0,0,0,80244,127277,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68792,3,0,'Attention, brawlers! $n has made a bargain with the Spirit Healers! Go ahead and die as much as you want!',14,0,100.0,0,0,80244,124363,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68794,0,0,'Attention, brawlers! $n has made a bargain with the Spirit Healers! Go ahead and die as much as you want!',14,0,100.0,0,0,80244,124363,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68963,3,0,'Bizmo\'s Boom Room has opened its doors to all brawlers, courtesy of $n!',14,0,100.0,0,0,80244,127276,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68990,0,0,'No! NO NO NO!',14,0,100.0,273,0,0,70660,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68991,0,0,'HOW THE... WHAT THE...  DAMMIT!',14,0,100.0,0,0,0,70663,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68992,0,0,'That\'s my $n!',14,0,100.0,21,0,34746,70129,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68992,3,0,'Alright $n!',14,0,100.0,4,0,34341,70126,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68994,3,0,'$n! $n! $n!',14,0,100.0,21,0,34758,70128,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (68994,4,0,'Bah! I had my whole paycheck riding on that one!',14,0,100.0,0,0,0,70659,0,'LegionCore');
