INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (114944,2,0,'1, 2, 3, JUMP!',14,0,100.0,0,0,80210,125098,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (115058,0,0,'Noooo!',14,0,100.0,0,0,0,128399,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (115797,0,0,'$n has turned in enough gold to bend the rules of the arena. Speak to a grunt if you\'d like to fight against a random brawler!',14,0,100.0,0,0,80244,124406,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (116692,0,0,'Come to me... with all your anguish!',14,0,100.0,0,0,0,125514,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (116743,0,0,'We\'re going to have a blast!',14,0,100.0,0,0,34341,125516,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (116743,1,0,'You\'ll see that I possess an explosive personality!',14,0,100.0,0,0,0,125515,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (116743,8,0,'They always blow up so fast.',12,0,100.0,0,0,34755,125545,0,'LegionCore');
